insert into public.themes (owner_id, slug, name, description, palette, materials, mood, is_preset) values
  (null, 'tech-smart-home', 'Tech / Smart Home', 'Clean lines, concealed cabling, ambient LED cove lighting and integrated smart controls.', array['#e8eaed', '#2b2f36', '#4f8cff', '#9aa3ad', '#ffffff']::text[], array['matte lacquer', 'brushed aluminium', 'tempered glass', 'acoustic fabric panels']::text[], array['sleek', 'connected', 'efficient', 'ambient']::text[], true),
  (null, 'minimalist', 'Minimalist', 'Less, but better. A pared-back palette, hidden storage and generous negative space.', array['#f5f3ef', '#d9d4cc', '#1f1f1f', '#b5ada1', '#ffffff']::text[], array['white oak', 'microcement', 'linen', 'matte white laminate']::text[], array['calm', 'uncluttered', 'airy', 'intentional']::text[], true),
  (null, 'cozy-warmth', 'Cozy Warmth', 'Layered textiles, warm 2700K lighting and earthy tones that invite you to stay in.', array['#e9d8c4', '#b5653a', '#7a4b2a', '#f3e9dc', '#a3826a']::text[], array['boucle', 'walnut', 'terracotta', 'wool throws']::text[], array['inviting', 'snug', 'warm', 'layered']::text[], true),
  (null, 'comfy', 'Comfy', 'Deep-seated sofas, soft rounded edges and family-friendly, washable fabrics.', array['#efe6da', '#8fa39a', '#d8c3a5', '#5f6b66', '#fff9f0']::text[], array['performance fabric', 'rattan', 'ash wood', 'cotton']::text[], array['relaxed', 'soft', 'family', 'lived-in']::text[], true),
  (null, 'classy-luxe', 'Classy / Luxe', 'Marble, brass accents, velvet and statement lighting for an elevated, hotel-like feel.', array['#1f2a2e', '#c9a96e', '#efe9e1', '#5b2333', '#8c8c8c']::text[], array['Calacatta marble', 'brushed brass', 'velvet', 'fluted panels']::text[], array['elegant', 'refined', 'dramatic', 'polished']::text[], true),
  (null, 'japandi', 'Japandi', 'Japanese restraint meets Scandinavian warmth: low furniture, natural textures, muted tones.', array['#ece6dc', '#a68a64', '#4a4239', '#c8bfb0', '#7d8471']::text[], array['light oak', 'washi paper', 'linen', 'stone']::text[], array['serene', 'grounded', 'natural', 'balanced']::text[], true),
  (null, 'scandinavian', 'Scandinavian', 'Bright, functional and cosy: pale woods, white walls and soft pastel accents.', array['#ffffff', '#e3ddd3', '#b8c4cc', '#d9b99b', '#3c3c3c']::text[], array['birch', 'wool', 'white-washed pine', 'ceramic']::text[], array['bright', 'hygge', 'functional', 'fresh']::text[], true),
  (null, 'industrial', 'Industrial', 'Raw concrete, black steel, exposed brick and Edison bulbs for a loft-inspired edge.', array['#6e6a65', '#2b2927', '#a0522d', '#c2bbb1', '#3f4a4f']::text[], array['concrete screed', 'black steel', 'reclaimed wood', 'leather']::text[], array['urban', 'raw', 'bold', 'loft']::text[], true),
  (null, 'modern-tropical', 'Modern Tropical', 'Built for the equator: breezy layouts, rattan, lush greens and humidity-friendly finishes.', array['#f2ede3', '#2f5d50', '#c79a5b', '#88a47c', '#ffffff']::text[], array['rattan', 'teak', 'terrazzo', 'linen']::text[], array['breezy', 'lush', 'resort', 'relaxed']::text[], true),
  (null, 'peranakan-modern', 'Peranakan Modern', 'A contemporary nod to Straits Chinese heritage: pastel tiles, carved wood and jewel tones.', array['#f4e9e1', '#2e8b8b', '#e8a0a8', '#1d3557', '#d4a017']::text[], array['encaustic tiles', 'carved teak', 'lacquer', 'porcelain']::text[], array['heritage', 'vibrant', 'playful', 'crafted']::text[], true)
